export default async function collect({ propertyId }, ctx) {
  if (!/^\d+$/.test(propertyId)) throw Error("Configure a GA4 property ID");
  const today = new Date(),
    iso = (d) => d.toISOString().slice(0, 10),
    now = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate())),
    previous = new Date(now);
  previous.setUTCFullYear(previous.getUTCFullYear() - 1);
  const shift = (d) => new Date(d.getTime() - 7 * 86400000),
    ranges = [
      { startDate: iso(shift(now)), endDate: iso(now) },
      { startDate: iso(shift(previous)), endDate: iso(previous) },
    ],
    metrics = [
      "screenPageViews",
      "totalUsers",
      "sessions",
      "sessionsPerUser",
      "averageSessionDuration",
      "ecommercePurchases",
      "averagePurchaseRevenue",
      "purchaseRevenue",
    ],
    tables = [];
  for (const range of ranges) {
    let offset = 0,
      rows = [];
    for (;;) {
      const res = await ctx.actions.call("google_analytics.run_report", {
        propertyId,
        dateRanges: [range],
        dimensions: ["date"],
        metrics,
        limit: 10000,
        offset,
      });
      const r = res?.report;
      if (!r || !Array.isArray(r.rows)) throw Error("Invalid GA4 report");
      const count = r.rowCount == null && r.rows.length === 0 ? 0 : r.rowCount;
      if (
        !Number.isSafeInteger(count) ||
        count < offset + r.rows.length ||
        (!r.rows.length && offset < count)
      )
        throw Error("Invalid GA4 page");
      for (const row of r.rows) {
        if (!Array.isArray(row.metricValues) || row.metricValues.length !== 8)
          throw Error("Invalid GA4 values");
        const values = row.metricValues.map(Number);
        if (values.some((x) => !Number.isFinite(x))) throw Error("Invalid GA4 number");
        rows.push(values);
      }
      offset += r.rows.length;
      if (offset === count) break;
    }
    if (!rows.length) throw Error("No daily data for period");
    tables.push(rows);
  }
  const names = [
      "Page views",
      "Daily users summed",
      "Sessions",
      "Sessions per user daily average",
      "Session duration seconds daily average",
      "Purchases",
      "Revenue per purchase daily average",
      "Purchase revenue",
    ],
    sum = (rows) =>
      names.map((_, i) => {
        let x = rows.reduce((a, r) => a + r[i], 0);
        return [3, 4, 6].includes(i) && rows.length ? x / rows.length : x;
      }),
    a = sum(tables[0]),
    b = sum(tables[1]);
  return {
    day: iso(now),
    facts: JSON.stringify({
      ranges,
      metrics: names.map((name, i) => ({
        name,
        recent: a[i],
        previous: b[i],
        changePercent: b[i] === 0 ? null : ((a[i] - b[i]) * 100) / b[i],
      })),
    }),
  };
}

