export default async function ({ day }, ctx) {
  const key = "ga108:" + day + ":email",
    s = await ctx.state.get(key);
  if (s?.status === "pending") throw Error("Inspect pending email " + key);
  if (s?.status === "done") return { key, send: false };
  await ctx.state.set(key, { status: "pending" });
  return { key, send: true };
}

